// ===== ResolveAI core logic: Understand -> Investigate -> Decide =====
const ORDERS = {
  "1021": { customer: "Ravi Kumar",   item: "Bluetooth Headphones", amount: 1499, status: "Delivered", date: "2026-10-02" },
  "1022": { customer: "Anjali Reddy", item: "Phone Case",           amount: 299,  status: "Delivered", date: "2026-10-03" },
  "1023": { customer: "Sai Teja",     item: "Smart Watch",          amount: 2999, status: "Shipped - arriving 9 Oct", date: "2026-10-04" },
  "1024": { customer: "Meena Devi",   item: "USB-C Cable",          amount: 249,  status: "Delivered", date: "2026-10-01" },
  "1025": { customer: "Kiran Babu",   item: "Laptop Stand",         amount: 899,  status: "Delayed - courier issue", date: "2026-09-28" },
  "1026": { customer: "Lakshmi P",    item: "Water Bottle",         amount: 399,  status: "Processing", date: "2026-10-06" }
};
const REFUND_LIMIT = 500;   // AI may auto-approve refunds up to this amount
const MIN_CONFIDENCE = 0.7;

function ruleClassify(msg) {
  const m = msg.toLowerCase();
  const idMatch = msg.match(/(\d{4})/);
  let intent = "other";
  if (/(refund|money back|return|damaged|broken|defective)/.test(m)) intent = "refund";
  else if (/(where|status|track|when will|deliver|arrive)/.test(m)) intent = "status";
  else if (/(complain|worst|bad service|cheat)/.test(m)) intent = "complaint";
  const angry = /(worst|angry|ridiculous|useless|terrible|cheat|fraud|never again|!!)/.test(m) || (msg.replace(/[^A-Z]/g, "").length > 15);
  return {
    intent, order_id: idMatch ? idMatch[1] : null,
    sentiment: angry ? "angry" : "calm",
    urgency: angry ? "high" : "low",
    confidence: intent === "other" ? 0.4 : 0.85,
    summary: msg.slice(0, 140)
  };
}

function decide(message, ai) {
  const oid = ai.order_id ? String(ai.order_id).replace(/\D/g, "") : null;
  const order = oid ? ORDERS[oid] : null;
  let route = "escalate", reply = "", action = "", reason = "";

  if (ai.sentiment === "angry" || ai.urgency === "high") reason = "Angry / urgent customer - needs human care";
  else if ((ai.confidence ?? 0) < MIN_CONFIDENCE) reason = "Low AI confidence";
  else if (!order) reason = oid ? "Order #" + oid + " not found" : "No order ID provided";
  else if (ai.intent === "status") {
    route = "status"; action = "Auto-replied with live order status";
    reply = "Hi " + order.customer + ", your order #" + oid + " (" + order.item + ") is: " + order.status + ".";
  } else if (ai.intent === "refund") {
    if (order.amount <= REFUND_LIMIT && order.status === "Delivered") {
      route = "refund"; action = "Refund of Rs." + order.amount + " auto-approved (within Rs." + REFUND_LIMIT + " limit)";
      reply = "Hi " + order.customer + ", sorry about your " + order.item + ". A refund of Rs." + order.amount + " for order #" + oid + " is approved and will reach you in 3-5 days.";
    } else reason = "Refund Rs." + order.amount + " exceeds auto-approval limit or item not delivered";
  } else reason = "Intent '" + ai.intent + "' needs a human";

  if (route === "escalate") {
    action = "Escalated to human agent";
    reply = "Thanks for reaching out. Your request has been prioritised and a support specialist will contact you shortly.";
  }
  return {
    ticket_id: "TKT-" + Date.now().toString().slice(-6),
    route, intent: ai.intent, sentiment: ai.sentiment, urgency: ai.urgency, confidence: ai.confidence,
    order_id: oid, order: order || null, reply, action,
    escalation: route === "escalate" ? {
      reason, summary: ai.summary,
      suggested_reply: order ? "Apologise, confirm order #" + oid + " (" + order.item + ", " + order.status + "), offer a resolution." : "Apologise and ask for the order ID."
    } : null,
    ai_source: ai.source
  };
}

const raw = $('Customer Message').first().json.body;
const req = typeof raw === 'string' ? JSON.parse(raw) : (raw || {});
const message = req.message || '';
let ai;
try {
  const text = $input.first().json.candidates[0].content.parts[0].text;
  ai = JSON.parse(text.replace(/```json|```/g, '').trim());
  ai.source = 'Gemini AI';
} catch (e) {
  ai = ruleClassify(message);
  ai.source = 'Rule-based fallback (AI unavailable)';
}
const out = decide(message, ai);
out.customer_message = message;
out.email = req.email || '';
return [{ json: out }];
